def name_operands(region,function_address,operation):
    if region=='Action' and function_address in FUNCTIONS:
        for address,expression in ((0xCF0B,'FirstPoint+FRenderProjectedPoint.Second'),(0xCF0D,'FirstPoint+FRenderProjectedPoint.First'),(0xCF0F,'FirstPoint+FRenderProjectedPoint.ClipCode'),(0xCF1B,'SecondPoint+FRenderProjectedPoint.Second'),(0xCF1D,'SecondPoint+FRenderProjectedPoint.First'),(0xCF1F,'SecondPoint+FRenderProjectedPoint.ClipCode')):
            operation=operation.replace('(#'+format(address,'04X')+')','(@ActionClipProductsState.'+expression+')')
        operation=operation.replace('(#CF03)','(@ActionClipPointWritersState.CornerBlock)').replace('(#CF07)','(@ActionClipCasesState.SeenFlags)').replace('(#9BA3)','(@ActionClipIntersectionsState.OutputSize)')
        operation=operation.replace('LD DE, #C071','LD DE, @Action.ContinueClipPolygon.Entry')
        operation=operation.replace('LD H, #8E','LD H, @ActionVertexGroupConst.WorkHigh').replace('LD H, #CF','LD H, @ActionPolygonConst.TableLowPage')
        operation=operation.replace('AND #F0','AND @ActionVertexCodeConst.InverseMask').replace('AND #0F','AND @ActionPolygonConst.OutsideMask').replace('CP #06','CP @ActionPolygonConst.MinimumBytes')
    for point in ('FirstPoint','SecondPoint'):
        operation=operation.replace('@ActionClipProductsState.'+point+'+FRenderProjectedPoint.','@ActionClipPoints.'+point+'.')
    return operation
